package com.example.ecommerce;
import com.example.ecommerce.entity.*; import com.example.ecommerce.service.*; import com.example.ecommerce.util.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.*;
public class Application { public static void main(String[] args){EntityManager em=JpaUtil.entityManager(); EntityTransaction tx=em.getTransaction(); try{tx.begin(); Category electronics=new Category("Electronics","Devices and accessories"); em.persist(electronics); Product headphones=new Product("Wireless Headphones","Noise cancelling",new BigDecimal("79.99"),20,electronics); em.persist(headphones); User user=new User("Asha Kumar","asha@example.com",PasswordUtil.hash("change-me")); em.persist(user); tx.commit(); CustomerOrder order=new OrderService(em).placeOrder(user.getId(),List.of(new OrderRequestItem(headphones.getId(),2))); System.out.println("Created order #"+order.getId()+" total: "+order.getTotal());}finally{em.close();JpaUtil.close();}} }
